#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

# Stop inherited tracing before reading any credentials. Never source the env file.
set +x
set +v
umask 077
REPO_ROOT=$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")/.." && pwd)
cd "$REPO_ROOT"
ENV_FILE="$REPO_ROOT/.env.local"
TOTAL_STAGES=5

[[ -t 0 && -t 1 ]] || { printf 'Run this wizard in an interactive terminal.\n' >&2; exit 1; }
command -v node >/dev/null || { warn 'Install Node 24 or later first.'; exit 1; }
node -e 'if (+process.versions.node.split(".")[0] < 24) process.exit(1)' || { warn 'Node 24 or later is required for the audit operator CLI.'; exit 1; }
[[ ! -L "$ENV_FILE" ]] || { warn 'Refusing a symlink at .env.local.'; exit 1; }
[[ ! -e "$ENV_FILE" || -f "$ENV_FILE" ]] || { warn '.env.local must be a regular file.'; exit 1; }
touch "$ENV_FILE"
chmod 600 "$ENV_FILE"
# The unchanged library uses mktemp for atomic upserts. Keep those private copies
# beside the explicitly selected destination, never in the shared /tmp directory.
TMPDIR=$(mktemp -d "$REPO_ROOT/.ims-setup.XXXXXX")
export TMPDIR
trap 'rm -rf -- "$TMPDIR"' EXIT
trap 'exit 130' INT
trap 'exit 143' TERM

must_confirm() { confirm "$1" || { warn 'Stopped; saved values remain in .env.local for a rerun.'; exit 1; }; }
check() { node scripts/ims-setup.mjs "$1" "$ENV_FILE"; }
capture_secret() {
  local key="$1" pattern="$2"
  while true; do
    ask_secret "$key" "Paste $key (Enter keeps a previously saved value):"
    [[ "${!key}" =~ $pattern ]] && break
    warn 'Unexpected secret format; paste only the generated value, without quotes.'
  done
  write_env "$key" "${!key}"
  unset "$key"
}

banner 'IMS operator setup'
say 'Only .env.local (mode 600) and private temporary copies beside it receive IMS secrets.'
say 'Temporary copies are deleted on exit. Do not record this terminal or run with shell tracing.'
say 'Audit keys belong only in the gateway CALLERS secret; use your password manager to edit it.'
say 'This wizard does not deploy services, migrate databases, or rotate keys automatically.'
must_confirm 'Continue with this storage destination and the five stages?'

stage 'Choose the Portal, IMS and gateway addresses'
say 'Use stable domains, not per-deployment preview addresses. Enter bare origins without a final slash.'
ask PORTAL_URL 'Portal origin:'
ask IMS_APP_URL 'Production IMS origin (currently https://br-sims.vercel.app):'
ask IMS_LOCAL_APP_URL 'Local IMS origin (the dev script uses https://localhost:3003):'
ask IMS_GATEWAY_URL 'Gateway origin (currently https://api-gateway.jude-nitram08.workers.dev):'
write_env PORTAL_URL "$PORTAL_URL"
write_env PORTAL_SYSTEM_NAME IMS
write_env IMS_APP_URL "$IMS_APP_URL"
write_env IMS_LOCAL_APP_URL "$IMS_LOCAL_APP_URL"
write_env IMS_GATEWAY_URL "$IMS_GATEWAY_URL"
check addresses
say 'IMS_APP_URL is the production value. For local development, replace it with IMS_LOCAL_APP_URL.'
must_confirm 'Are these the intended trusted origins?'

stage 'Register IMS with the Portal'
open_url "$PORTAL_URL"
say 'In a separate private terminal, open the Portal repository with its operator database configured.'
say 'IMS must already exist in the Portal seed. Ticket #2 owns the seven Modules and Administrator grants.'
warn 'Registration replaces ALL IMS callbacks and immediately invalidates the old backend secret.'
say 'If you already have the current secret and both callbacks are registered, skip the command and paste that secret.'
say 'Otherwise coordinate the rotation with every IMS deployment using this Portal database.'
must_confirm 'Ready to register or reuse the current registration?'
printf -v registration_command 'npm run system:register -- IMS %q %q' \
  "$IMS_LOCAL_APP_URL/api/portal/callback" "$IMS_APP_URL/api/portal/callback"
step "Run in the Portal repo: $registration_command"
step 'The backend secret is shown once. Paste only that value below; the wizard hides it.'
capture_secret PORTAL_SYSTEM_SECRET '^iss_[A-Za-z0-9_-]{43}$'
check portal
must_confirm 'Confirmed both callback URLs in the registration output?'

stage 'Create the audit keys'
open_url "$IMS_GATEWAY_URL/audit/docs"
say 'In a separate private terminal, open audit-logs with its owner DATABASE_URL_MIGRATIONS configured.'
say 'Use the existing database; do not run db:migrate on an already provisioned service.'
say 'Reuse the existing scoped keys from your password manager on a rerun.'
must_confirm 'Create new keys only if the existing IMS keys are unavailable?'
step 'Run in audit-logs: npm run key -- create write:IMS'
step 'Save the one-time output in your password manager for ims.auditKey; do not paste it into IMS.'
step 'Run in audit-logs: npm run key -- create read:admin'
step 'Save that output for ims-audit-read.auditKey. This key can read all Sources: restrict it to the IMS backend.'
must_confirm 'Have both audit keys ready, with write:IMS and read:admin scopes respectively?'

stage 'Add IMS to the gateway Caller list'
open_url 'https://dash.cloudflare.com/'
say 'For each Caller key, Enter keeps the saved value. Generate only when the value is missing.'
for key in IMS_GATEWAY_CALLER_KEY IMS_GATEWAY_AUDIT_READ_CALLER_KEY; do
  if [[ -n "$(_existing "$key" || true)" ]]; then
    capture_secret "$key" '^[a-f0-9]{64}$'
  else
    generated=$(node scripts/ims-setup.mjs new-key)
    write_env "$key" "$generated"
    unset generated
  fi
done
check hashes
say 'Open your password manager record containing the complete current CALLERS JSON.'
say 'Preserve EVERY existing entry. Do not use gen-callers.mjs: it replaces the entire list.'
say 'Add/update the following two entries using the hashes above and the corresponding audit keys:'
say '{"name":"ims","app":"IMS","systemCode":"IMS","keyHash":"<ims hash>","auditKey":"<write:IMS key>","auditScope":"write:IMS"}'
say '{"name":"ims-audit-read","app":"IMS","systemCode":"IMS","keyHash":"<ims-audit-read hash>","auditKey":"<read:admin key>","auditScope":"read:admin"}'
say 'Use Workers & Pages → your api-gateway Worker → Settings → Variables and Secrets → CALLERS → Edit.'
say 'If the UI differs, use the gateway CLI: npx wrangler secret put CALLERS, and paste the complete JSON when prompted.'
warn 'Publishing CALLERS affects every connected System. Never paste a partial list or put plaintext Caller keys in it.'
must_confirm 'Have you preserved all other entries and are you ready to publish CALLERS?'
step 'Save the complete JSON as the encrypted CALLERS secret and deploy/apply the Worker update.'
must_confirm 'Is the updated CALLERS secret active on the gateway?'
check gateway

stage 'Record the deployment values'
say 'Copy values from .env.local directly into the IMS hosting project’s Production environment settings:'
step 'PORTAL_URL, PORTAL_SYSTEM_NAME, PORTAL_SYSTEM_SECRET, IMS_APP_URL, IMS_GATEWAY_URL'
step 'IMS_GATEWAY_CALLER_KEY, IMS_GATEWAY_AUDIT_READ_CALLER_KEY'
say 'Keep the existing DATABASE_URL. IMS_LOCAL_APP_URL is only an operator helper; do not deploy it.'
say 'Keep IMS_DEV_BYPASS unset in production and previews. Never use NEXT_PUBLIC_ for credentials.'
say 'Tickets #5 and #11 will consume these values; this ticket does not enable sign-in or audit in IMS.'
say 'After #5, verify real handoff from the Portal using both registered callbacks. This probe checked credentials only.'
must_confirm 'Have you saved the deployment values in the intended secret store?'
finish
